'use strict';

function prepareEnrollment(input) {
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    throw new TypeError('input must be an object');
  }
  if (typeof input.name !== 'string' || typeof input.email !== 'string' ||
      typeof input.secret !== 'string') {
    throw new TypeError('invalid fields');
  }

  const name = input.name.trim();
  const email = input.email.trim();
  const parts = email.split('@');
  if (name.length === 0 || parts.length !== 2 || parts[0].length === 0 ||
      parts[1].length === 0 || /\s/.test(email) || input.secret.length < 8) {
    throw new TypeError('invalid fields');
  }

  const clientTag = input.clientTag === undefined ? null : input.clientTag;
  if (clientTag !== null && typeof clientTag !== 'string') {
    throw new TypeError('invalid clientTag');
  }

  return { name, email, secret: input.secret, clientTag };
}

module.exports = { prepareEnrollment };

