'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['prepareEnrollment']);
const { prepareEnrollment } = api;

for (const bad of [null, undefined, [], 'x', 1]) assert.throws(() => prepareEnrollment(bad), TypeError);
assert.throws(() => prepareEnrollment({ name: 1, email: 'a@b', secret: '12345678' }), TypeError);
assert.throws(() => prepareEnrollment({ name: '   ', email: 'a@b', secret: '12345678' }), TypeError);
assert.throws(() => prepareEnrollment({ name: 'A', email: 1, secret: '12345678' }), TypeError);
for (const email of ['', 'ab', '@b', 'a@', 'a@@b', 'a b@c', 'a@b c', 'a\tb@c']) {
  assert.throws(() => prepareEnrollment({ name: 'A', email, secret: '12345678' }), TypeError);
}
assert.throws(() => prepareEnrollment({ name: 'A', email: 'a@b', secret: 12345678 }), TypeError);
assert.throws(() => prepareEnrollment({ name: 'A', email: 'a@b', secret: '1234567' }), TypeError);
assert.throws(() => prepareEnrollment({ name: 'A', email: 'a@b', secret: '12345678', clientTag: 1 }), TypeError);

const input = {
  name: '  Ada Lovelace  ',
  email: '  ADA@Example.COM  ',
  secret: '  secret  ',
  clientTag: '',
  ignored: { value: 1 }
};
const before = structuredClone(input);
const result = prepareEnrollment(input);
assert.deepEqual(result, {
  name: 'Ada Lovelace',
  email: 'ada@example.com',
  secret: '  secret  ',
  clientTag: ''
});
assert.notStrictEqual(result, input);
assert.deepEqual(input, before);

assert.deepEqual(prepareEnrollment({
  name: 'N', email: 'N@X', secret: 'abcdefgh'
}), { name: 'N', email: 'n@x', secret: 'abcdefgh', clientTag: null });
assert.deepEqual(prepareEnrollment({
  name: ' X ', email: ' x@y ', secret: '        ', clientTag: ' tag '
}), { name: 'X', email: 'x@y', secret: '        ', clientTag: ' tag ' });

